SELECT CAST(TRY_CAST(hc.coachee_emp_id AS INTEGER) AS VARCHAR) AS agent_id, CAST(hc.coaching_date AS DATE) AS coaching_date, CAST(date_add('day', 4, date_trunc('week', CAST(hc.coaching_date AS TIMESTAMP))) AS DATE) AS period, hc.coaching_status, hc.coaching_type, hc.coaching_topic, hc.behavior, hc.behavior_selected, hc.expert_acknowledged FROM hive.care.l2_asurion_coachdb_coachdb_helixcoaching hc WHERE CAST(hc.coaching_date AS DATE) BETWEEN DATE '2026-06-20' AND DATE '2026-07-31' AND hc.coaching_status IN ( 'Submitted','Excused' )
